-- MERCADO RAÍZ — schema del dominio en PostgreSQL (SPEC-25).
-- Idempotente: db.js lo ejecuta en cada apertura del pool, por eso
-- todo lleva IF NOT EXISTS.
--
-- Convenciones: ids GENERATED BY DEFAULT AS IDENTITY (permite los
-- ids explícitos del seed; BY DEFAULT, no ALWAYS), flags
-- activo/revocado como INTEGER 0/1, fechas TIMESTAMPTZ con default
-- now(), dinero DOUBLE PRECISION.

CREATE TABLE IF NOT EXISTS proveedores (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre TEXT NOT NULL,
  contacto TEXT,
  telefono TEXT,
  email TEXT,
  tiempo_entrega_dias INTEGER NOT NULL DEFAULT 1,
  -- SPEC-26 (R26.4): lead como rango + datos comerciales. El lead
  -- esperado de cálculo es (min+max)/2 cuando hay rango, si no
  -- tiempo_entrega_dias (convención documentada en SPEC-26).
  tiempo_entrega_min_dias INTEGER,
  tiempo_entrega_max_dias INTEGER,
  confiabilidad_pct INTEGER CHECK (confiabilidad_pct BETWEEN 0 AND 100),
  pedido_minimo_monto DOUBLE PRECISION NOT NULL DEFAULT 0,
  costo_envio DOUBLE PRECISION NOT NULL DEFAULT 0,
  categorias_cubiertas TEXT[] NOT NULL DEFAULT '{}',
  activo INTEGER NOT NULL DEFAULT 1,
  fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS productos (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sku TEXT UNIQUE NOT NULL,
  nombre TEXT NOT NULL,
  marca TEXT,
  ean TEXT,
  categoria TEXT NOT NULL,
  stock_actual INTEGER NOT NULL DEFAULT 0,
  stock_minimo INTEGER NOT NULL,
  precio_venta DOUBLE PRECISION NOT NULL,
  proveedor_id INTEGER NOT NULL,
  ubicacion TEXT,
  estado TEXT NOT NULL DEFAULT 'OK'
    CHECK (estado IN ('OK', 'STOCK_BAJO', 'CRITICO')),
  fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT now(),

  FOREIGN KEY (proveedor_id) REFERENCES proveedores(id)
);

CREATE INDEX IF NOT EXISTS idx_productos_sku ON productos(sku);
CREATE INDEX IF NOT EXISTS idx_productos_estado ON productos(estado);
CREATE INDEX IF NOT EXISTS idx_productos_stock ON productos(stock_actual);

CREATE TABLE IF NOT EXISTS ordenes_compra (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  orden_id TEXT UNIQUE NOT NULL,
  producto_id INTEGER NOT NULL,
  proveedor_id INTEGER NOT NULL,
  cantidad INTEGER NOT NULL,
  precio_unitario DOUBLE PRECISION NOT NULL,
  monto_total DOUBLE PRECISION NOT NULL,
  estado TEXT NOT NULL DEFAULT 'PENDIENTE_APROBACION'
    CHECK (estado IN ('PENDIENTE_APROBACION', 'APROBADA', 'RECHAZADA', 'ENVIADA', 'RECIBIDA')),
  requiere_aprobacion INTEGER NOT NULL DEFAULT 0,
  analisis_ia TEXT,
  aprobado_por TEXT,
  motivo_rechazo TEXT,
  fecha_aprobacion TIMESTAMPTZ,
  -- SPEC-30 (T30.1): ciclo hacia el proveedor — enviada (la OC ya
  -- se le mandó) y recibida (llegó el camión → suma stock).
  enviado_por TEXT,
  fecha_envio TIMESTAMPTZ,
  cantidad_recibida INTEGER,
  recibido_por TEXT,
  fecha_recepcion TIMESTAMPTZ,
  -- SPEC-30 (T30.4): la alerta que originó la OC — trazabilidad
  -- pedido del buyer → alerta atendida (FK se agrega abajo,
  -- alertas aún no existe en este punto del script).
  alerta_id INTEGER,
  fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now(),
  fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT now(),

  FOREIGN KEY (producto_id) REFERENCES productos(id),
  FOREIGN KEY (proveedor_id) REFERENCES proveedores(id)
);

-- Upgrade idempotente para DBs creadas antes de SPEC-30.
ALTER TABLE ordenes_compra ADD COLUMN IF NOT EXISTS enviado_por TEXT;
ALTER TABLE ordenes_compra ADD COLUMN IF NOT EXISTS fecha_envio TIMESTAMPTZ;
ALTER TABLE ordenes_compra ADD COLUMN IF NOT EXISTS cantidad_recibida INTEGER;
ALTER TABLE ordenes_compra ADD COLUMN IF NOT EXISTS recibido_por TEXT;
ALTER TABLE ordenes_compra ADD COLUMN IF NOT EXISTS fecha_recepcion TIMESTAMPTZ;
ALTER TABLE ordenes_compra ADD COLUMN IF NOT EXISTS alerta_id INTEGER;

CREATE INDEX IF NOT EXISTS idx_ordenes_estado ON ordenes_compra(estado);
CREATE INDEX IF NOT EXISTS idx_ordenes_fecha ON ordenes_compra(fecha_creacion);

CREATE TABLE IF NOT EXISTS historial_stock (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  producto_id INTEGER NOT NULL,
  tipo_movimiento TEXT NOT NULL
    CHECK (tipo_movimiento IN ('VENTA', 'REPOSICION', 'AJUSTE', 'DEVOLUCION')),
  cantidad_anterior INTEGER NOT NULL,
  cantidad_nueva INTEGER NOT NULL,
  diferencia INTEGER NOT NULL,
  referencia TEXT,
  usuario TEXT,
  fecha TIMESTAMPTZ NOT NULL DEFAULT now(),

  FOREIGN KEY (producto_id) REFERENCES productos(id)
);

CREATE INDEX IF NOT EXISTS idx_historial_producto ON historial_stock(producto_id);
CREATE INDEX IF NOT EXISTS idx_historial_fecha ON historial_stock(fecha);

CREATE TABLE IF NOT EXISTS usuarios (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  nombre TEXT NOT NULL,
  rol TEXT NOT NULL CHECK (rol IN ('APROBADOR', 'GERENTE', 'ADMIN', 'SERVICIO', 'BUYER')),
  password_hash TEXT NOT NULL,
  avatar_url TEXT,
  activo INTEGER NOT NULL DEFAULT 1,
  intentos_fallidos INTEGER NOT NULL DEFAULT 0,
  bloqueado_hasta TIMESTAMPTZ,
  ultimo_login TIMESTAMPTZ,
  token_version INTEGER NOT NULL DEFAULT 0,
  fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Refresh tokens opacos (SPEC-23): solo se persiste el SHA-256 del
-- token; `familia` agrupa rotaciones para reuse detection — un token
-- ya usado revoca la familia completa.
CREATE TABLE IF NOT EXISTS refresh_tokens (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  usuario_id INTEGER NOT NULL,
  token_hash TEXT NOT NULL,
  familia TEXT NOT NULL,
  csrf_hash TEXT NOT NULL,
  expira_en TIMESTAMPTZ NOT NULL,
  revocado INTEGER NOT NULL DEFAULT 0,
  user_agent TEXT,
  ip TEXT,
  creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),

  FOREIGN KEY (usuario_id) REFERENCES usuarios(id)
);

CREATE INDEX IF NOT EXISTS idx_refresh_token_hash ON refresh_tokens(token_hash);
CREATE INDEX IF NOT EXISTS idx_refresh_familia ON refresh_tokens(familia);
CREATE INDEX IF NOT EXISTS idx_refresh_usuario ON refresh_tokens(usuario_id);

-- SPEC-26 (R26.1): ventas como hechos de negocio — distinto de
-- historial_stock (posiciones de stock). La demanda del agente y
-- el endpoint de estadísticas se calculan sobre esta tabla.
CREATE TABLE IF NOT EXISTS ventas (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  producto_id INTEGER NOT NULL,
  fecha DATE NOT NULL,
  unidades INTEGER NOT NULL CHECK (unidades > 0),
  canal TEXT NOT NULL CHECK (canal IN ('POS', 'WEB', 'MAYOR')),
  referencia TEXT,

  FOREIGN KEY (producto_id) REFERENCES productos(id)
);

CREATE INDEX IF NOT EXISTS idx_ventas_producto_fecha ON ventas(producto_id, fecha);
CREATE INDEX IF NOT EXISTS idx_ventas_fecha ON ventas(fecha);

-- SPEC-26 (R26.4) — upgrades para bases ya creadas (CREATE IF NOT
-- EXISTS no altera tablas existentes; idempotente).
ALTER TABLE proveedores ADD COLUMN IF NOT EXISTS tiempo_entrega_min_dias INTEGER;
ALTER TABLE proveedores ADD COLUMN IF NOT EXISTS tiempo_entrega_max_dias INTEGER;
ALTER TABLE proveedores ADD COLUMN IF NOT EXISTS confiabilidad_pct INTEGER
  CHECK (confiabilidad_pct BETWEEN 0 AND 100);
ALTER TABLE proveedores ADD COLUMN IF NOT EXISTS pedido_minimo_monto DOUBLE PRECISION NOT NULL DEFAULT 0;
ALTER TABLE proveedores ADD COLUMN IF NOT EXISTS costo_envio DOUBLE PRECISION NOT NULL DEFAULT 0;
ALTER TABLE proveedores ADD COLUMN IF NOT EXISTS categorias_cubiertas TEXT[] NOT NULL DEFAULT '{}';

-- SPEC-27: precios por proveedor. Un producto puede comprarse a
-- varios proveedores a distinto costo/lead; el principal se
-- denormaliza en productos.proveedor_id. costo_unitario es lo que
-- paga el supermercado (productos.precio_venta es lo que paga el
-- cliente → margen = 1 - costo/venta).
CREATE TABLE IF NOT EXISTS producto_proveedor (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  producto_id INTEGER NOT NULL,
  proveedor_id INTEGER NOT NULL,
  costo_unitario DOUBLE PRECISION NOT NULL,
  lead_dias INTEGER,
  es_principal INTEGER NOT NULL DEFAULT 0,
  activo INTEGER NOT NULL DEFAULT 1,
  fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now(),

  UNIQUE (producto_id, proveedor_id),
  FOREIGN KEY (producto_id) REFERENCES productos(id),
  FOREIGN KEY (proveedor_id) REFERENCES proveedores(id)
);

CREATE INDEX IF NOT EXISTS idx_pp_producto ON producto_proveedor(producto_id);

-- Upgrade SPEC-27: bases con precio_unitario viejo lo renombran.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name='productos' AND column_name='precio_unitario'
               AND table_schema = current_schema()) THEN
    ALTER TABLE productos RENAME COLUMN precio_unitario TO precio_venta;
  END IF;
END $$;

-- SPEC-29: alertas operativas — el motor de reglas (R29.3) las
-- genera, el buyer las consume en /alertas. `alertas_meta` guarda
-- el throttle de la evaluación lazy.
CREATE TABLE IF NOT EXISTS alertas (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tipo TEXT NOT NULL
    CHECK (tipo IN ('QUIEBRE', 'RIESGO_LEAD', 'DEAD_STOCK', 'ORDEN_PENDIENTE')),
  producto_id INTEGER,
  orden_id INTEGER,
  severidad TEXT NOT NULL DEFAULT 'MEDIA'
    CHECK (severidad IN ('ALTA', 'MEDIA', 'BAJA')),
  mensaje TEXT NOT NULL,
  leida INTEGER NOT NULL DEFAULT 0,
  fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now(),

  FOREIGN KEY (producto_id) REFERENCES productos(id),
  FOREIGN KEY (orden_id) REFERENCES ordenes_compra(id)
);

CREATE INDEX IF NOT EXISTS idx_alertas_leida ON alertas(leida);
CREATE INDEX IF NOT EXISTS idx_alertas_tipo ON alertas(tipo);

-- SPEC-30 (T30.4): la OC registra la alerta que la originó (FK +
-- una OC por alerta — respaldo del guard leida=0 del endpoint).
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint c
                 JOIN pg_namespace n ON n.oid = c.connamespace
                 WHERE c.conname = 'ordenes_compra_alerta_id_fkey'
                   AND n.nspname = current_schema()) THEN
    ALTER TABLE ordenes_compra
      ADD CONSTRAINT ordenes_compra_alerta_id_fkey
      FOREIGN KEY (alerta_id) REFERENCES alertas(id);
  END IF;
END $$;
CREATE UNIQUE INDEX IF NOT EXISTS idx_ordenes_alerta
  ON ordenes_compra(alerta_id) WHERE alerta_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS alertas_meta (
  clave TEXT PRIMARY KEY,
  valor TEXT NOT NULL
);

-- SPEC-29 (R29.1): el rol BUYER entra al CHECK de usuarios. Drop
-- idempotente del constraint viejo (nombre auto-generado por PG).
DO $$ BEGIN
  -- solo re-crea si la definición vieja no incluye BUYER — evita DDL
  -- en cada openDb() una vez migrada la base.
  IF EXISTS (SELECT 1 FROM pg_constraint c
             JOIN pg_namespace n ON n.oid = c.connamespace
             WHERE c.conname = 'usuarios_rol_check'
               AND n.nspname = current_schema()
               AND pg_get_constraintdef(c.oid) NOT LIKE '%BUYER%') THEN
    ALTER TABLE usuarios DROP CONSTRAINT usuarios_rol_check;
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint c
                 JOIN pg_namespace n ON n.oid = c.connamespace
                 WHERE c.conname = 'usuarios_rol_check'
                   AND n.nspname = current_schema()) THEN
    ALTER TABLE usuarios ADD CONSTRAINT usuarios_rol_check
      CHECK (rol IN ('APROBADOR', 'GERENTE', 'ADMIN', 'SERVICIO', 'BUYER'));
  END IF;
END $$;
